<script setup>
import {ref,computed,onMounted,onBeforeUnmount,nextTick} from 'vue'
import {Activity,Users,Phone,PhoneIncoming,PhoneOutgoing,Pause,RefreshCw,ArrowUpRight,Search,X,Clock,CheckCircle2,Voicemail,Radio,Filter} from 'lucide-vue-next'
import {voiceApi as api,stamp} from '../voice/operations'
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())
defineProps({canConfigure:{type:Boolean,default:true}})
const filters=ref({from:today(),to:today(),queue_id:'',campaign_id:''})
const state=ref(null),calls=ref(null),error=ref(''),busy=ref(false),automatic=ref(true),tab=ref('team'),search=ref(''),agentState=ref(''),now=ref(Date.now()),updated=ref(0),stale=ref(false)
const callFilters=ref({page:1,result:'',direction:'',q:'',user_id:'',live:false,attempted:false})
const modal=ref(null),modalEl=ref(null),mutation=ref(false),modalError=ref('')
const states={connected:{label:'Em chamada',color:'#25805e'},manual:{label:'Manual',color:'#b46e28'},dialing:{label:'Discando',color:'#3d6fbd'},idle:{label:'Disponível',color:'#7f8b77'},wrapup:{label:'Pós-atendimento',color:'#7864b1'},tabulation:{label:'Tabulando',color:'#7864b1'},paused:{label:'Em pausa',color:'#bd9338'},reserved:{label:'Preparando',color:'#3d6fbd'},review:{label:'A conferir',color:'#bf6260'},machine:{label:'Caixa postal',color:'#aa7070'},offline:{label:'Offline',color:'#a2a5a0'}}
const label=k=>states[k]?.label||k
const color=k=>states[k]?.color||'#7f8b77'
const visibleTeam=computed(()=>state.value?.agents.filter(a=>(!agentState.value||a.state===agentState.value)&&(!search.value||a.name.toLocaleLowerCase().includes(search.value.toLocaleLowerCase())))||[])
const groups=computed(()=>Object.entries(states).map(([key,s])=>({key,...s,total:state.value?.agent_counts[key]||0})))
const outcomeColors={human:'#25805e',connected:'#88a482',machine:'#b78fca',fax:'#b78fca',answer_unknown:'#c89b3b',no_answer:'#a7b0ba',busy:'#d2ad72',failed:'#c6746d',cancelled:'#b0aca5',dialing:'#5885c9',reserved:'#5885c9',unknown:'#c89b3b',waiting:'#5885c9',abandoned:'#c6746d',no_agent:'#c6746d',ended:'#a7b0ba'}
const outcomeStyle=computed(()=>{const rs=state.value?.results||[],total=rs.reduce((n,r)=>n+r.total,0);let position=0;return {background:total?`conic-gradient(${rs.map(r=>{let start=position;position+=r.total/total*100;return `${outcomeColors[r.key]||'#a7b0ba'} ${start}% ${position}%`}).join(',')})`:'#eeeee6'}})
const expired=ref(false)
const teamTotal=computed(()=>state.value?.agents.length||0)
const clockValue=s=>{if(!s)return '—';const seconds=Math.max(0,Math.floor((now.value-new Date(s).getTime())/1000));return duration(seconds)}
const duration=s=>s==null?'—':`${Math.floor(s/3600)?String(Math.floor(s/3600)).padStart(2,'0')+':':''}${String(Math.floor(s/60)%60).padStart(2,'0')}:${String(Math.floor(s%60)).padStart(2,'0')}`
const elapsed=c=>c.started_at?duration(Math.max(0,Math.floor(((c.ended_at?new Date(c.ended_at).getTime():now.value)-new Date(c.started_at).getTime())/1000))):'—'
const qs=o=>new URLSearchParams(Object.entries(o).filter(([,v])=>v!==''&&v!==null&&v!==false).map(([k,v])=>[k,v===true?'1':v])).toString()
let timer,tick,disposed=false,rerun=false,restoreFocus
async function load(){
 if(busy.value){rerun=true;return}busy.value=true;error.value=''
 const key=JSON.stringify([filters.value,callFilters.value]);const f={...filters.value},cf={...callFilters.value}
 try{
  const [s,c]=await Promise.all([api('/supervision?'+qs(f)),api('/supervision/calls?'+qs({...f,...cf}))])
  if(disposed)return
  if(key!==JSON.stringify([filters.value,callFilters.value])){rerun=true;return}
  state.value=s;calls.value=c.calls;updated.value=Date.now();now.value=Date.parse(s.generated_at);stale.value=false;expired.value=false
 }catch(e){if(!disposed){error.value=e.message;stale.value=true}}
 finally{busy.value=false;if(rerun&&!disposed){rerun=false;load()}}
}
function apply(){callFilters.value.page=1;load()}
function reset(){filters.value={from:today(),to:today(),queue_id:'',campaign_id:''};callFilters.value={page:1,result:'',direction:'',q:'',user_id:'',live:false,attempted:false};agentState.value='';search.value='';load()}
function drill(result='',user='',live=false,attempted=false){callFilters.value={...callFilters.value,page:1,result,direction:'',q:'',user_id:user,live,attempted};tab.value='calls';load()}
async function openModal(value){restoreFocus=document.activeElement;modalError.value='';modal.value=value;await nextTick();modalEl.value?.querySelector('button')?.focus()}
function closeModal(){if(mutation.value)return;modal.value=null;restoreFocus?.focus()}
function modalKeys(e){if(e.key!=='Tab')return;const items=[...modalEl.value.querySelectorAll('button:not(:disabled),a[href],input,select,textarea,summary')];if(!items.length)return;const first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}
async function pauseQueue(){mutation.value=true;modalError.value='';try{const {queue,channel}=modal.value;await api('/supervision/queues/'+queue.id+'/pause','POST',{channel,revision:queue.revision});mutation.value=false;closeModal();await load()}catch(e){modalError.value=e.message;await load()}finally{mutation.value=false}}
function visibility(){if(!document.hidden&&automatic.value)load()}
onMounted(()=>{load();timer=setInterval(()=>{if(automatic.value&&!document.hidden)load()},10000);tick=setInterval(()=>{expired.value=!!updated.value&&Date.now()-updated.value>=30000;if(updated.value&&Date.now()-updated.value<30000&&!stale.value)now.value+=1000},1000);document.addEventListener('visibilitychange',visibility)})
onBeforeUnmount(()=>{disposed=true;clearInterval(timer);clearInterval(tick);document.removeEventListener('visibilitychange',visibility)})
</script>
<template>
<section class="supervision">
 <header class="sv-heading"><div><span class="eyebrow">OPERAÇÃO EM FOCO</span><h1>Supervisão ao vivo<span class="sv-live-dot" :class="{stale:stale||!automatic||expired}"/></h1><p>Sua equipe, suas filas e cada conversa. Tudo no mesmo lugar.</p></div><div class="sv-header-actions"><label class="sv-toggle"><input type="checkbox" v-model="automatic" @change="automatic&&load()">Atualizar a cada 10 s</label><button class="secondary" :disabled="busy" @click="load"><RefreshCw :size="15" :class="{spinning:busy}"/> Atualizar</button></div></header>
 <form class="sv-filters" @submit.prevent="apply"><label><span>Fila</span><select v-model="filters.queue_id" @change="apply"><option value="">Todas as filas</option><option v-for="q in state?.catalog.queues||[]" :key="q.id" :value="q.id">{{q.name}}</option></select></label><label><span>Cadência</span><select v-model="filters.campaign_id" @change="apply"><option value="">Todas as cadências</option><option v-for="c in state?.catalog.campaigns||[]" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label><span>De</span><input type="date" v-model="filters.from" required></label><label><span>Até</span><input type="date" v-model="filters.to" required></label><button class="secondary" :disabled="busy"><Filter :size="14"/> Aplicar</button><button type="button" class="sv-text-btn" @click="reset">Hoje · limpar</button></form>
 <p v-if="error" class="sv-error" role="alert">{{error}} <span v-if="state">Exibindo a última consulta. Os cronômetros ficam suspensos quando os dados estão desatualizados.</span></p>
 <p v-if="!state&&!error" class="sv-empty">Preparando sua visão da operação…</p>
 <template v-if="state">
 <div class="sv-stamp"><span><Radio :size="13"/> {{stale||expired?'Dados sem atualização':automatic?'Acompanhamento automático':'Atualização manual'}} · última consulta {{stamp(state.generated_at)}}</span><span>Período em São Paulo · equipe e chamadas em curso mostram o estado atual</span></div>
 <p v-if="state.operation_paused" class="sv-warning">A operação está pausada pela supervisão. Novos atendimentos seguem os controles de Saúde e limites.</p>
 <div class="sv-kpis">
  <button @click="drill('','',false,true)"><span><Phone :size="17"/> Chamadas no período</span><strong>{{state.summary.attempts}}</strong><small>Saídas iniciadas + entradas recebidas</small></button>
  <button @click="drill('','',true)"><span><Activity :size="17"/> Em curso agora</span><strong>{{state.live_total}}</strong><small>Inclui reservas e resultados a conferir</small></button>
  <button @click="drill('human')"><span><CheckCircle2 :size="17"/> Pessoas identificadas</span><strong>{{state.summary.humans}}</strong><small>Detecção ou confirmação do atendente</small></button>
  <button @click="drill('no_answer')"><span><PhoneOutgoing :size="17"/> Não atenderam</span><strong>{{state.summary.no_answer}}</strong><small>Resultado informado pela telefonia</small></button>
  <button @click="drill('machine')"><span><Voicemail :size="17"/> Caixa postal</span><strong>{{state.summary.machines}}</strong><small>Classificação registrada na chamada</small></button>
 </div>
 <nav class="sv-tabs" aria-label="Visões da supervisão"><button v-for="[key,text] in [['team','Equipe'],['queues','Filas'],['campaigns','Cadências'],['calls','Chamadas e resultados']]" :key="key" :class="{active:tab===key}" @click="tab=key">{{text}} <span v-if="key==='team'">{{teamTotal}}</span><span v-if="key==='queues'">{{state.queues.length}}</span></button></nav>
 <div v-if="tab==='team'" class="sv-team-layout">
  <article class="sv-card sv-team"><header><div><h2>O pulso da equipe</h2><p>Disponibilidade e ocupação, sem contar um agente duas vezes.</p></div><Users :size="23"/></header>
   <div class="sv-state-bar" aria-label="Distribuição dos agentes por estado"><button v-for="g in groups.filter(g=>g.total)" :key="g.key" :style="{width:(g.total/teamTotal*100)+'%',background:g.color}" :title="`${g.total} · ${g.label}`" :aria-label="`${g.total} · ${g.label}`" @click="agentState=agentState===g.key?'':g.key"/></div>
   <div class="sv-state-legend"><button v-for="g in groups.filter(g=>g.total||['connected','idle','paused','wrapup'].includes(g.key))" :key="g.key" :class="{chosen:agentState===g.key}" @click="agentState=agentState===g.key?'':g.key"><i :style="{background:g.color}"/><b>{{g.total}}</b> {{g.label}}</button></div>
   <div class="sv-search"><Search :size="16"/><input v-model="search" aria-label="Buscar agente" placeholder="Buscar agente…"><button v-if="agentState" class="sv-text-btn" @click="agentState=''">Limpar estado</button></div>
   <div class="sv-scroll"><table><thead><tr><th>Agente / filas</th><th>Agora</th><th>Tempo</th><th></th></tr></thead><tbody><tr v-for="a in visibleTeam" :key="a.id"><td><div class="sv-person"><span class="sv-avatar">{{a.name.split(' ').slice(0,2).map(n=>n[0]).join('')}}</span><div><strong>{{a.name}}</strong><small>{{a.queues.map(q=>q.name).join(' · ')||'Sem fila atribuída'}}</small></div></div></td><td><span class="sv-badge" :style="{'--state-color':color(a.state)}"><i/>{{label(a.state)}}</span><small>{{a.detail}}</small><small v-if="a.call">{{a.call.phone}}</small></td><td class="sv-clock"><Clock :size="13"/> {{clockValue(a.since)}}<small v-if="a.until">Até {{new Date(a.until).toLocaleTimeString('pt-BR')}}</small></td><td><button class="sv-icon-btn" :aria-label="'Detalhes de '+a.name" @click="openModal({type:'agent',agent:a})"><ArrowUpRight :size="18"/></button></td></tr></tbody></table></div>
   <p v-if="!visibleTeam.length" class="sv-empty">Nenhum atendente neste filtro.</p><footer>“Em chamada” indica conexão técnica. A confirmação de pessoa aparece nos resultados. Tempos antigos sem registro aparecem como —.</footer>
  </article>
  <article class="sv-card sv-results"><header><div><h2>Cada tentativa conta</h2><p>Resultados do período selecionado</p></div></header><div class="sv-donut" :style="outcomeStyle"><div><strong>{{state.summary.records}}</strong><span>registros</span></div></div><div class="sv-result-list"><button v-for="r in state.results" :key="r.key" @click="drill(r.key)"><i :style="{background:outcomeColors[r.key]||'#a7b0ba'}"/><span>{{r.label}}</span><b>{{r.total}}</b><ArrowUpRight :size="14"/></button></div><p v-if="!state.results.length" class="sv-empty">Os resultados aparecem após as primeiras chamadas.</p><footer>Inclui reservas sem discagem. Clique em um resultado para abrir as chamadas.</footer></article>
 </div>
 <div v-if="tab==='queues'" class="sv-queue-grid"><article v-for="q in state.queues" :key="q.id" class="sv-card sv-queue"><header><span class="sv-kicker">{{ ({inbound:'RECEPTIVO',outbound:'SAÍDA',mixed:'ENTRADA E SAÍDA'})[q.direction] }}</span><span class="sv-badge" :style="{'--state-color':q.available?'#25805e':'#93988b'}">{{q.available}} disponíveis</span></header><h2>{{q.name}}</h2><p class="sv-number">{{q.voice_number||'Número não configurado'}}</p><div class="sv-queue-metrics"><div><strong>{{q.assigned}}</strong><small>na equipe</small></div><div><strong>{{q.busy}}</strong><small>ocupados</small></div><div><strong>{{q.campaign_ids.length}}</strong><small>cadências</small></div></div><div class="sv-channel" v-if="q.direction!=='inbound'"><span><PhoneOutgoing :size="15"/>Saída <b>{{q.status==='running'?'Habilitada':'Pausada'}}</b></span><button v-if="q.status==='running'" class="secondary" @click="openModal({type:'pause',queue:q,channel:'outbound'})"><Pause :size="13"/> Pausar</button></div><div class="sv-channel" v-if="q.direction!=='outbound'"><span><PhoneIncoming :size="15"/>Entrada <b>{{q.inbound_enabled?'Habilitada':'Pausada'}}</b></span><button v-if="q.inbound_enabled" class="secondary" @click="openModal({type:'pause',queue:q,channel:'inbound'})"><Pause :size="13"/> Pausar</button></div><p class="sv-queue-note">{{q.schedule_open?'Dentro do horário da fila':'Fora do horário da fila'}} · {{q.method==='programmable_voice'?'Twilio API':'SIP'}} · {{q.mode==='progressive'?'Progressivo':'Preview'}}</p><footer><button class="sv-text-btn" @click="filters.queue_id=q.id;tab='team';apply()">Acompanhar equipe <ArrowUpRight :size="14"/></button><a v-if="canConfigure" href="#/queues">Configurar filas</a></footer></article><p v-if="!state.queues.length" class="sv-empty">Nenhuma fila corresponde à seleção.</p></div>
 <div v-if="tab==='campaigns'" class="sv-queue-grid"><article v-for="c in state.campaigns" :key="c.id" class="sv-card sv-campaign"><span class="sv-kicker">CADÊNCIA DE VOZ</span><h2>{{c.name}}</h2><span class="sv-badge" :style="{'--state-color':c.status==='testing'?'#25805e':'#bd9338'}">{{c.status==='testing'?'Habilitada':c.status==='paused'?'Pausada':c.status}}</span><div class="sv-campaign-total"><strong>{{c.attempts}}</strong><span>tentativas no período</span></div><p>{{state.queues.filter(q=>q.campaign_ids.includes(c.id)).map(q=>q.name).join(' · ')||'Sem fila neste filtro'}}</p><footer><button class="sv-text-btn" @click="filters.campaign_id=c.id;tab='team';apply()">Acompanhar <ArrowUpRight :size="14"/></button><a v-if="canConfigure" :href="'#/cadences/voice/'+c.id">Abrir cadência</a></footer></article><p v-if="!state.campaigns.length" class="sv-empty">Nenhuma cadência corresponde à seleção.</p></div>
 <article v-if="tab==='calls'" class="sv-card sv-calls"><header><div><h2>{{callFilters.live?'Chamadas em curso agora':'Histórico de chamadas'}}</h2><p>{{callFilters.live?'Chamadas com capacidade ainda reservada, independentemente do período.':'Uma linha por chamada. Abra os detalhes para conferir o retorno da telefonia.'}}</p></div><button class="sv-text-btn" @click="callFilters={page:1,result:'',direction:'',q:'',user_id:'',live:false,attempted:false};load()">Limpar detalhes</button></header><form class="sv-call-filters" @submit.prevent="apply"><label><span>Resultado</span><select v-model="callFilters.result" @change="apply"><option value="">Todos</option><option v-for="r in state.result_options||state.results" :value="r.key" :key="r.key">{{r.label}}</option></select></label><label><span>Direção</span><select v-model="callFilters.direction" @change="apply"><option value="">Entrada e saída</option><option value="outbound">Saída</option><option value="inbound">Entrada</option></select></label><label><span>Contato, telefone ou agente</span><input v-model="callFilters.q" placeholder="Pesquisar…" maxlength="100"></label><button class="secondary" :disabled="busy">Buscar</button></form><p v-if="callFilters.attempted" class="sv-warning">Somente chamadas iniciadas. Preparações sem discagem ficam fora deste filtro.</p><p v-if="callFilters.user_id" class="sv-warning">Detalhes filtrados pelo agente selecionado.</p><div class="sv-scroll"><table><thead><tr><th>Contato / telefone</th><th>Cadência / fila</th><th>Agente</th><th>Resultado</th><th>Início</th><th>Duração total</th><th></th></tr></thead><tbody><tr v-for="c in calls?.data||[]" :key="c.direction+c.id"><td><strong>{{c.contact_name||(c.direction==='inbound'?'Chamada recebida':'Contato não identificado')}}</strong><small>{{c.phone}}</small></td><td>{{c.campaign_name||'Sem cadência'}}<small>{{c.queue_name||'Sem fila'}} · {{c.direction==='inbound'?'Entrada':'Saída'}}</small></td><td>{{c.agent_name||'Sem agente'}}</td><td><span class="sv-badge" :style="{'--state-color':outcomeColors[c.result]||'#7f8b77'}">{{c.result_label}}</span><small>{{c.disposition_label||'Sem tabulação'}}</small></td><td>{{stamp(c.started_at||c.created_at)}}</td><td class="sv-clock">{{elapsed(c)}}</td><td><button class="sv-icon-btn" :aria-label="'Detalhes da chamada para '+c.phone" @click="openModal({type:'call',call:c})"><ArrowUpRight :size="17"/></button></td></tr></tbody></table></div><p v-if="!calls?.data.length" class="sv-empty">Nenhuma chamada encontrada. Experimente outro período ou filtro.</p><footer class="sv-pagination"><button class="secondary" :disabled="busy||!calls||calls.current_page<=1" @click="callFilters.page--;load()">Anterior</button><span>{{calls?.total||0}} chamadas · página {{calls?.current_page||1}} de {{calls?.last_page||1}}</span><button class="secondary" :disabled="busy||!calls||calls.current_page>=calls.last_page" @click="callFilters.page++;load()">Próxima</button></footer></article>
 </template>
 <Teleport to="body"><div v-if="modal" class="sv-overlay"><section ref="modalEl" class="sv-dialog" role="dialog" aria-modal="true" aria-labelledby="sv-dialog-title" @keydown="modalKeys"><button class="sv-close secondary" aria-label="Fechar detalhes" :disabled="mutation" @click="closeModal"><X :size="18"/></button><span class="sv-kicker">SUPERVISÃO</span><h2 id="sv-dialog-title">{{modal.type==='pause'?'Pausar '+(modal.channel==='inbound'?'entrada':'saída'):modal.type==='agent'?modal.agent.name:'Detalhes da chamada'}}</h2><p v-if="modalError" class="sv-error" role="alert">{{modalError}}</p><template v-if="modal.type==='pause'"><p>{{modal.queue.name}}</p><p>{{modal.channel==='outbound'?'Impede novas discagens automáticas desta fila. A permissão de discagem manual continua independente.':'Impede novas distribuições receptivas desta fila.'}} Chamadas em andamento continuam.</p><div class="sv-dialog-actions"><button class="secondary" :disabled="mutation" @click="closeModal">Cancelar</button><button class="primary" :disabled="mutation" @click="pauseQueue">{{mutation?'Pausando…':'Confirmar pausa'}}</button></div></template><template v-else-if="modal.type==='agent'"><span class="sv-badge" :style="{'--state-color':color(modal.agent.state)}">{{label(modal.agent.state)}}</span><p>{{modal.agent.detail}}</p><p v-for="q in modal.agent.queues" :key="q.id">{{q.name}} · {{modal.agent.selected_queue_ids.includes(q.id)?'Selecionada':'Não selecionada'}}</p><p>Estado capturado ao abrir os detalhes.</p><button class="primary" @click="drill('',modal.agent.id);closeModal()">Ver chamadas deste agente</button></template><template v-else><p class="sv-detail-phone">{{modal.call.phone}}</p><span class="sv-badge" :style="{'--state-color':outcomeColors[modal.call.result]||'#7f8b77'}">{{modal.call.result_label}}</span><dl><dt>Contato</dt><dd>{{modal.call.contact_name||'Não identificado'}}</dd><dt>Origem / número da empresa</dt><dd>{{modal.call.origin||'—'}}</dd><dt>Agente</dt><dd>{{modal.call.agent_name||'Sem agente'}}</dd><dt>Cadência</dt><dd>{{modal.call.campaign_name||'Sem cadência'}}</dd><dt>Fila</dt><dd>{{modal.call.queue_name||'Sem fila'}}</dd><dt>Início</dt><dd>{{stamp(modal.call.started_at||modal.call.created_at)}}</dd><dt>Conexão técnica</dt><dd>{{stamp(modal.call.answered_at)}}</dd><dt>Encerramento</dt><dd>{{stamp(modal.call.ended_at)}}</dd><dt>Segundos informados pela telefonia</dt><dd>{{modal.call.bill_seconds??'—'}}</dd><dt>Tabulação</dt><dd>{{modal.call.disposition_label||'Não registrada'}}</dd></dl><p v-if="modal.call.notes">{{modal.call.notes}}</p><details><summary>Retorno técnico</summary><dl><dt>Status</dt><dd>{{modal.call.status}}</dd><dt>Retorno de discagem</dt><dd>{{modal.call.dial_status||'Não informado'}}</dd><dt>Causa</dt><dd>{{modal.call.cause||'Não informada'}}</dd><dt>Classificação AMD</dt><dd>{{modal.call.answer_classification}}</dd><dt>Recado na caixa postal</dt><dd>{{modal.call.voicemail_status}}</dd><dt>ID da chamada</dt><dd>{{modal.call.id}}</dd></dl></details><p class="sv-detail-note">“Não atendeu” é o retorno da operadora e não comprova que o aparelho tocou. Caixa postal não é conversa com uma pessoa.</p></template></section></div></Teleport>
</section>
</template>
<style>
